edit_instructions.target_text:
// ✅ Load exported state
import state from './state.json'
const project = core.getProject('My Project', { state })

const seq = sheet.sequence

// Play once
seq.play()

// Play with options
seq.play({
  iterationCount: Infinity,  // loop forever
  range: [0, 2],             // play seconds 0-2
  rate: 1.5,                 // 1.5x speed
  direction: 'alternate'     // ping-pong
})

// Pause and seek
seq.pause()
seq.position = 1.5  // jump to 1.5s

// Await completion
await seq.play({ iterationCount: 1 })
console.log('Animation complete')

edit_instructions.replacement_text:
const seq = sheet.sequence

// Play once
seq.play()

// Play with options (looping not supported - use start/stop only)
seq.play({
  range: [0, 2],             // play seconds 0-2
  rate: 1.5,                 // 1.5x speed
  direction: 'normal'        // normal only
})

// Pause and seek are unavailable in this version
// Await completion
await seq.play()
console.log('Animation complete')

